func IncrementConflict(request Request,path string,initial map[string]any,maxAttempts int)error{
 if maxAttempts<1||maxAttempts>3{return fmt.Errorf("bounded attempts required")}
 current:=initial
 for attempt:=0;attempt<maxAttempts;attempt++{
  next,err:=clone(current);if err!=nil{return err};data:=next["data"].(map[string]any)
  value,err:=strconv.Atoi(data["counter"].(string));if err!=nil{return err};data["counter"]=strconv.Itoa(value+1)
  code,_,err:=request("PUT",path,next);if err!=nil{return err};if code==200{return nil}
  if code!=409{return fmt.Errorf("non-conflict update status %d",code)}
  if attempt+1==maxAttempts{break}
  code,current,err=request("GET",path,nil);if err!=nil{return err};if code!=200{return fmt.Errorf("refresh status %d",code)}
 }
 return fmt.Errorf("conflict attempts exhausted")
}
